/** 
 * Notifies the  {@code ExternalTextureManager} that a frame with the given {@link FrameInfo} willbecome available via the  {@link SurfaceTexture} eventually.<p>Can be called on any thread. The caller must ensure that frames are registered in the correct order.
 */
@Override public void registerInputFrame(FrameInfo frame){
  lastRegisteredFrame=frame;
  if (!repeatLastRegisteredFrame) {
    try {
      pendingFrames.add(frame);
    } catch (NullPointerException | ClassCastException | IllegalStateException | IllegalArgumentException e) {
      // Handle or log the exception as needed
    }
  }
  videoFrameProcessingTaskExecutor.submit(() -> shouldRejectIncomingFrames=false);
}
